type SharePasscodeRecord = { failures: number; lastFailure: number; lockedUntil: number };
const sharePasscodeLockouts = new Map<string, SharePasscodeRecord>();
const SHARE_PASSCODE_WINDOW_MS = 3_600_000;
const SHARE_PASSCODE_LOCKOUT_THRESHOLDS = [
  { failures: 5,  lockoutMs: 60_000 },
  { failures: 10, lockoutMs: 300_000 },
  { failures: 15, lockoutMs: 900_000 },
  { failures: 20, lockoutMs: 3_600_000 },
];

function applySharePasscodeLockout(rec: SharePasscodeRecord): void {
  for (let i = SHARE_PASSCODE_LOCKOUT_THRESHOLDS.length - 1; i >= 0; i--) {
    if (rec.failures >= SHARE_PASSCODE_LOCKOUT_THRESHOLDS[i].failures) {
      rec.lockedUntil = Date.now() + SHARE_PASSCODE_LOCKOUT_THRESHOLDS[i].lockoutMs;
      break;
    }
  }
}

function pruneSharePasscodeLockouts(now: number): void {
  if (sharePasscodeLockouts.size > 50000) {
    const cutoff = now - SHARE_PASSCODE_WINDOW_MS;
    for (const [k, v] of sharePasscodeLockouts) {
      if (v.lastFailure < cutoff) sharePasscodeLockouts.delete(k);
    }
  }
}

function getHeader(req: Request, name: string): string | undefined {
  const value = req.headers[name];
  if (Array.isArray(value)) {
    return value[0];
  }
  return value;
}

function getUserId(req: Request): string {
  return (req as any)._authenticatedUserId || "";
}

function getParam(req: Request, name: string): string {
  const value = req.params[name];
  if (Array.isArray(value)) {
    return value[0] || "";
  }
  return value || "";
}

type AuthRouteHandler = (req: Request, res: Response, userId: string) => Promise<any>;

function authRoute(handler: AuthRouteHandler) {
  return async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      if (!userId) return res.status(401).json({ error: "Unauthorized" });
      await handler(req, res, userId);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  };
}

const recordRequestAudit = createRequestAuditRecorder(
  (entry) => storage.createAuditLog(entry),
  (event) => logger.critical("audit", event),
);

function auditLog(req: Request, action: string, resourceType?: string | null, resourceId?: string | null, metadata?: object) {
  const userId = getUserId(req) || null;
  recordRequestAudit(req, {
    userId,
    action,
    resourceType: resourceType || null,
    resourceId: resourceId || null,
    ipAddress: req.ip || getHeader(req, "x-forwarded-for") || null,
    userAgent: getHeader(req, "user-agent") || null,
    metadata: metadata || null,
  });
}

