function categorizeLabTest(title: string): string {
  const lower = (title || "").toLowerCase();
  if (lower.includes("cbc") || lower.includes("blood count") || lower.includes("hemoglobin") || lower.includes("hematocrit") || lower.includes("wbc") || lower.includes("rbc") || lower.includes("platelet")) return "hematology";
  if (lower.includes("cholesterol") || lower.includes("lipid") || lower.includes("hdl") || lower.includes("ldl") || lower.includes("triglyceride")) return "lipid_panel";
  if (lower.includes("glucose") || lower.includes("hba1c") || lower.includes("a1c") || lower.includes("hemoglobin a1c") || lower.includes("insulin")) return "metabolic";
  if (lower.includes("tsh") || lower.includes("t3") || lower.includes("t4") || lower.includes("thyroid")) return "thyroid";
  if (lower.includes("bun") || lower.includes("creatinine") || lower.includes("gfr") || lower.includes("sodium") || lower.includes("potassium") || lower.includes("calcium") || lower.includes("electrolyte") || lower.includes("cmp") || lower.includes("bmp")) return "renal_metabolic";
  if (lower.includes("ast") || lower.includes("alt") || lower.includes("alp") || lower.includes("bilirubin") || lower.includes("albumin") || lower.includes("liver") || lower.includes("hepatic")) return "liver";
  if (lower.includes("urinalysis") || lower.includes("urine")) return "urinalysis";
  if (lower.includes("vitamin") || lower.includes("iron") || lower.includes("ferritin") || lower.includes("b12") || lower.includes("folate")) return "nutritional";
  if (lower.includes("psa") || lower.includes("cea") || lower.includes("ca-125") || lower.includes("tumor")) return "tumor_markers";
  if (lower.includes("covid") || lower.includes("flu") || lower.includes("strep") || lower.includes("culture")) return "infectious";
  return "general";
}

async function createAuthSession(userId: string, req: Request): Promise<{ accessToken: string; refreshToken: string }> {
  const rawAccessToken = randomBytes(32).toString("hex");
  const rawRefreshToken = randomBytes(32).toString("hex");
  const hashedAccessToken = createHash("sha256").update(rawAccessToken).digest("hex");
  const hashedRefreshToken = createHash("sha256").update(rawRefreshToken).digest("hex");

  const userAgent = getHeader(req, "user-agent") || "unknown";
  const deviceId = createHash("sha256").update(`${userAgent}:${req.ip || "unknown"}`).digest("hex").substring(0, 16);

  const now = new Date();
  const accessExpiry = new Date(now.getTime() + 15 * 60 * 1000);
  const refreshExpiry = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  await storage.createUserSession({
    userId,
    deviceId,
    deviceName: userAgent.substring(0, 100),
    deviceType: userAgent.includes("Mobile") ? "mobile" : "desktop",
    platform: userAgent.includes("iPhone") || userAgent.includes("iPad") ? "ios" : userAgent.includes("Android") ? "android" : "web",
    ipAddress: req.ip || getHeader(req, "x-forwarded-for") || null,
    accessToken: hashedAccessToken,
    refreshToken: hashedRefreshToken,
    accessTokenExpiresAt: accessExpiry,
    refreshTokenExpiresAt: refreshExpiry,
  });

  return { accessToken: rawAccessToken, refreshToken: rawRefreshToken };
}

