// Monitoring and metrics tracking
const metrics = {
  requestCount: 0,
  errorCount: 0,
  startTime: Date.now(),
  endpoints: new Map<string, { count: number; errors: number; totalTime: number }>(),
};

function aggregateMetricsByHour(metrics: any[]): { hour: string; requests: number; errors: number; avgLatency: number }[] {
  const hourlyData: Record<string, { requests: number; errors: number; totalLatency: number }> = {};
  
  for (const metric of metrics) {
    const hour = new Date(metric.createdAt).toISOString().substring(0, 13) + ":00";
    
    if (!hourlyData[hour]) {
      hourlyData[hour] = { requests: 0, errors: 0, totalLatency: 0 };
    }
    
    hourlyData[hour].requests++;
    hourlyData[hour].totalLatency += metric.latencyMs || 0;
    if (metric.statusCode && metric.statusCode >= 400) {
      hourlyData[hour].errors++;
    }
  }
  
  return Object.entries(hourlyData)
    .map(([hour, data]) => ({
      hour,
      requests: data.requests,
      errors: data.errors,
      avgLatency: data.requests > 0 ? Math.round(data.totalLatency / data.requests) : 0,
    }))
    .sort((a, b) => a.hour.localeCompare(b.hour));
}

function trackRequest(endpoint: string, duration: number, isError: boolean) {
  metrics.requestCount++;
  if (isError) metrics.errorCount++;
  
  const existing = metrics.endpoints.get(endpoint) || { count: 0, errors: 0, totalTime: 0 };
  existing.count++;
  if (isError) existing.errors++;
  existing.totalTime += duration;
  metrics.endpoints.set(endpoint, existing);
}

// Enhanced error handler with proper logging
function handleApiError(res: Response, error: unknown, message: string, endpoint: string, startTime: number) {
  const duration = Date.now() - startTime;
  trackRequest(endpoint, duration, true);
  
  logger.error(`[${endpoint}] ${message}`, { error: error instanceof Error ? error.message : error });
  
  if (error instanceof Error && error.message.includes("not found")) {
    return res.status(404).json({ error: message, details: "Resource not found" });
  }
  if (error instanceof Error && error.message.includes("invalid")) {
    return res.status(400).json({ error: message, details: "Invalid request data" });
  }
  
  res.status(500).json({ error: message });
}

// FHIR Mapping helper functions
function getNestedValue(obj: any, path: string): any {
  const parts = path.split(".");
  let current = obj;
  for (const part of parts) {
    if (current === undefined || current === null) return undefined;
    // Handle array notation like "category[0].coding[0].code"
    const match = part.match(/^(\w+)\[(\d+)\]$/);
    if (match) {
      current = current[match[1]]?.[parseInt(match[2])];
    } else {
      current = current[part];
    }
  }
  return current;
}

function applyTransformation(value: any, transform: any): any {
  if (!transform) return value;
  
  const { type, config } = transform;
  
  switch (type) {
    case "format":
      // Format string with template
      if (config?.template && typeof value === "object") {
        return config.template.replace(/\{(\w+)\}/g, (_: string, key: string) => value[key] || "");
      }
      return value;
    
    case "concat":
      // Concatenate values with separator
      if (Array.isArray(value)) {
        return value.join(config?.separator || " ");
      }
      return value;
    
    case "date":
      // Format date
      if (value) {
        const date = new Date(value);
        return date.toISOString();
      }
      return value;
    
    case "number":
      // Convert to number
      return Number(value);
    
    case "boolean":
      // Convert to boolean
      return Boolean(value);
    
    case "lowercase":
      return String(value).toLowerCase();
    
    case "uppercase":
      return String(value).toUpperCase();
    
    case "trim":
      return String(value).trim();
    
    case "regex":
      // Extract with regex
      if (config?.pattern) {
        const match = String(value).match(new RegExp(config.pattern));
        return match ? (config.group !== undefined ? match[config.group] : match[0]) : value;
      }
      return value;
    
    case "lookup":
      // Look up value in a table
      if (config?.table && typeof config.table === "object") {
        return config.table[value] ?? (config.default || value);
      }
      return value;
    
    case "first":
      // Get first element of array
      return Array.isArray(value) ? value[0] : value;
    
    case "join":
      // Join array elements
      if (Array.isArray(value)) {
        return value.map(v => typeof v === "object" ? JSON.stringify(v) : v).join(config?.separator || ", ");
      }
      return value;
    
    default:
      return value;
  }
}

