interface DeployedVersionInfo {
  sha: string;
  buildTimestamp: string;
  nodeEnv: string;
}

let cachedVersionInfo: DeployedVersionInfo | null = null;

function getDeployedVersionInfo(): DeployedVersionInfo {
  if (cachedVersionInfo) return cachedVersionInfo;

  let sha = process.env.GIT_SHA || "unknown";
  let buildTimestamp = process.env.BUILD_TIMESTAMP || "unknown";

  // The deploy build writes a version.json next to the bundled server so the
  // running process reflects the actual deployed commit, not whatever the
  // runtime container happens to have checked out.
  const candidates = [
    path.join(process.cwd(), "server_dist", "version.json"),
    path.join(process.cwd(), "version.json"),
  ];
  for (const candidate of candidates) {
    try {
      const raw = fs.readFileSync(candidate, "utf-8");
      const parsed = JSON.parse(raw) as Partial<DeployedVersionInfo>;
      if (parsed.sha) sha = parsed.sha;
      if (parsed.buildTimestamp) buildTimestamp = parsed.buildTimestamp;
      break;
    } catch {
      // file missing or unreadable; try next candidate
    }
  }

  // Dev fallback: if we still don't know the SHA, ask git directly. This
  // path is only ever hit outside a deploy build, so it's fine to shell out.
  if (sha === "unknown") {
    try {
      sha = execSync("git rev-parse --short HEAD", {
        encoding: "utf-8",
        stdio: ["ignore", "pipe", "ignore"],
      }).trim() || "unknown";
    } catch {
      // git not available; leave as "unknown"
    }
  }

  cachedVersionInfo = {
    sha,
    buildTimestamp,
    nodeEnv: process.env.NODE_ENV || "unknown",
  };
  return cachedVersionInfo;
}


